import { useEffect, useState } from 'react'
import { catalogPerformanceRepo, clientesRepo, ejecutivosRepo } from './data/repositories.js'
import { drillDownRepo } from './data/drillDown.js'
import { opportunityRepo } from './data/opportunities.js'
import { commercialPriorityRepo } from './data/commercialPriority.js'
import { getCatalogAccess } from './data/catalogLink.js'
const money=v=>Number(v||0).toLocaleString('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0})
const pct=v=>v==null?'—':`${(Number(v)*100).toFixed(1)}%`
const label=v=>v==null||v===''?'—':String(v)
const ACTION_TYPES=[['volver','Volver a contactar'],['pidio','Cliente pidió seguimiento'],['sin_stock','Resolver falta de stock'],['otro','Otra acción']]
function OpportunitySummary({rows,loading,onRefresh,onOpen}){const total=rows.reduce((a,r)=>a+Number(r.oportunidadEstimada||0),0);const clients=new Set(rows.map(r=>r.clienteKey)).size;const products=new Set(rows.map(r=>r.sku)).size;return <section className="cc-opportunity-summary"><div className="cc-section-head"><div><span className="cc-subtitle">OPORTUNIDAD COMERCIAL</span><h2>Potencial recuperable detectado</h2><p>Oportunidades explicables construidas desde historial, frecuencia, stock y precio del cliente.</p></div><button onClick={onRefresh} disabled={loading}>{loading?'Calculando…':'Actualizar'}</button></div><div className="cc-kpis"><div><span>POTENCIAL ESTIMADO</span><b>{money(total)}</b></div><div><span>OPORTUNIDADES</span><b>{rows.length.toLocaleString('es-CL')}</b></div><div><span>CLIENTES</span><b>{clients.toLocaleString('es-CL')}</b></div><div><span>PRODUCTOS</span><b>{products.toLocaleString('es-CL')}</b></div></div>{rows.length?<div className="cc-opportunity-list">{rows.slice(0,10).map((o,i)=><button className="cc-opportunity-card" key={`${o.clienteKey}-${o.sku}-${i}`} onClick={()=>onOpen(o)}><div><b>{label(o.producto)}</b><span>{label(o.nombreCliente||o.clienteKey)}</span></div><div><small>BRECHA</small><strong>{Number(o.brechaEstimada||0).toLocaleString('es-CL')}</strong></div><div><small>DÍAS</small><strong>{Number(o.diasSinCompra||0).toLocaleString('es-CL')}</strong></div><div><small>POTENCIAL</small><strong>{money(o.oportunidadEstimada)}</strong></div><div><span>{label(o.razon)}</span> →</div></button>)}</div>:<div className="cc-empty">No se detectaron oportunidades con las señales actuales.</div>}</section>}
function CommercialPriority({rows,loading,onRefresh,onOpen}){const urgent=rows.filter(r=>r.priority==='URGENTE').length;const high=rows.filter(r=>r.priority==='ALTA').length;const potential=rows.reduce((a,r)=>a+Number(r.potential||0),0);return <section className="cc-commercial-priority"><div className="cc-section-head"><div><span className="cc-subtitle">V14 → PRIORIDAD COMERCIAL</span><h2>A quién atacar primero</h2><p>Prioridad explicable combinando riesgo, inactividad, caída de venta y potencial de recuperación.</p></div><button onClick={onRefresh} disabled={loading}>{loading?'Calculando…':'Actualizar'}</button></div><div className="cc-kpis"><div><span>URGENTES</span><b>{urgent.toLocaleString('es-CL')}</b></div><div><span>PRIORIDAD ALTA</span><b>{high.toLocaleString('es-CL')}</b></div><div><span>CLIENTES PRIORIZADOS</span><b>{rows.length.toLocaleString('es-CL')}</b></div><div><span>POTENCIAL ASOCIADO</span><b>{money(potential)}</b></div></div>{rows.length?<div className="cc-priority-list">{rows.slice(0,10).map((r,i)=><button className="cc-priority-row" key={`${r.clienteKey}-${i}`} onClick={()=>onOpen(r)}><span><b>{label(r.nombreCliente)}</b><small>{label(r.ejecutivo)} · {label(r.zona)}</small></span><strong>{label(r.priority)}</strong><span>{r.score}/100</span><span>{Number(r.dias_sin_comprar??r.diasSinComprar??0).toLocaleString('es-CL')} días</span><span>{money(r.potential)}</span><span>{label(r.reason)} →</span></button>)}</div>:<div className="cc-empty">No hay clientes priorizados con las señales actuales.</div>}</section>}
function ChannelTerritory({rows,loading,onRefresh}){const [canal,setCanal]=useState('TODOS');const canales=['TODOS',...new Set(rows.map(r=>r.canal))];const visible=canal==='TODOS'?rows:rows.filter(r=>r.canal===canal);const max=Math.max(1,...visible.map(r=>r.venta));return <section className="cc-channel-territory"><div className="cc-section-head"><div><span className="cc-subtitle">EMPRESA → CANAL → ZONA</span><h2>Venta por canal y territorio</h2><p>Lectura ejecutiva del negocio sin mezclar la operación de Terreno, KAM y Televenta.</p></div><button onClick={onRefresh} disabled={loading}>{loading?'Actualizando…':'Actualizar'}</button></div><div className="cc-channel-tabs">{canales.map(c=><button key={c} className={canal===c?'active':''} onClick={()=>setCanal(c)}>{c}</button>)}</div>{visible.length?<div className="cc-channel-list">{visible.map((r,i)=><div className="cc-channel-row" key={`${r.canal}-${r.zona}-${i}`}><div className="cc-channel-label"><b>{r.canal}</b><span>{r.zona}</span></div><div className="cc-channel-bar"><i style={{width:`${Math.max(3,(r.venta/max)*100)}%`}}/></div><div className="cc-channel-value"><b>{money(r.venta)}</b><span>{pct(r.avance)} meta · {r.clientes} clientes · {r.riesgo} riesgo</span></div></div>)}</div>:<div className="cc-empty">Sin datos territoriales disponibles.</div>}</section>}
function B2BAttribution({rows,loading,onRefresh,onOpenDrill}){const [canal,setCanal]=useState('TODOS');const channels=['TODOS',...new Set(rows.map(r=>r.canal))];const visible=canal==='TODOS'?rows:rows.filter(r=>r.canal===canal);return <section className="cc-b2b-attribution"><div className="cc-section-head"><div><span className="cc-subtitle">B2B → ATRIBUCIÓN COMERCIAL</span><h2>De catálogo a venta</h2><p>Cada pedido cerrado del catálogo se atribuye al canal y territorio del cliente.</p></div><button onClick={onRefresh} disabled={loading}>{loading?'Actualizando…':'Actualizar'}</button></div><div className="cc-channel-tabs">{channels.map(c=><button key={c} className={canal===c?'active':''} onClick={()=>setCanal(c)}>{c}</button>)}</div>{visible.length?<div className="cc-b2b-attribution-table"><div className="cc-b2b-head"><span>CANAL</span><span>ZONA</span><span>VENTA</span><span>PEDIDOS</span><span>CLIENTES</span><span/></div>{visible.map((r,i)=><button className="cc-b2b-row" key={`${r.canal}-${r.zona}-${i}`} onClick={()=>onOpenDrill(r.canal,r.zona)}><b>{r.canal}</b><span>{r.zona}</span><strong>{money(r.venta)}</strong><span>{r.pedidos.toLocaleString('es-CL')}</span><span>{r.clientes.toLocaleString('es-CL')}</span><span>→</span></button>)}</div>:<div className="cc-empty">Sin pedidos B2B atribuibles.</div>}</section>}
function DrillDown({selection,onClose,onClient}){const [executives,setExecutives]=useState([]);const [selectedExec,setSelectedExec]=useState(null);const [clients,setClients]=useState([]);const [orders,setOrders]=useState([]);const [loading,setLoading]=useState(false);useEffect(()=>{let alive=true;setLoading(true);setSelectedExec(null);setClients([]);drillDownRepo.ejecutivosPorTerritorio(selection.canal,selection.zona).then(v=>{if(alive)setExecutives(v)}).finally(()=>alive&&setLoading(false));return()=>{alive=false}},[selection.canal,selection.zona]);useEffect(()=>{if(!selectedExec)return;let alive=true;setLoading(true);Promise.all([drillDownRepo.carteraEjecutivo(selectedExec.id),drillDownRepo.pedidosB2BCliente(selectedExec.id)]).then(([c,p])=>{if(alive){setClients(c);setOrders(p)}}).finally(()=>alive&&setLoading(false));return()=>{alive=false}},[selectedExec]);return <div className="cc-drill-panel"><div className="cc-section-head"><div><span className="cc-subtitle">DRILL-DOWN</span><h2>{selection.canal} / {selection.zona}</h2><p>Canal → zona → ejecutivo → cliente.</p></div><button onClick={onClose}>Cerrar</button></div>{loading&&<div className="cc-empty">Cargando detalle…</div>}{!selectedExec&&executives.length>0&&<div className="cc-drill-list">{executives.map(e=><button key={e.id} onClick={()=>setSelectedExec(e)}><b>{label(e.nombre)}</b><span>{label(e.rol)} · {label(e.zona)}</span><strong>{money(e.venta)} · {e.clientes} clientes · {e.riesgo} riesgo</strong>→</button>)}</div>}{selectedExec&&<div className="cc-drill-detail"><button onClick={()=>setSelectedExec(null)}>← Ejecutivos</button><h3>{label(selectedExec.nombre)}</h3><div className="cc-kpis"><div><span>VENTA MTD</span><b>{money(selectedExec.venta)}</b></div><div><span>META</span><b>{money(selectedExec.meta)}</b></div><div><span>AVANCE</span><b>{pct(selectedExec.avance)}</b></div><div><span>CLIENTES</span><b>{selectedExec.clientes}</b></div><div><span>RIESGO</span><b>{selectedExec.riesgo}</b></div></div><div className="cc-drill-client-list"><h4>Cartera</h4>{clients.map(c=><button key={c.id||c.cliente_key} onClick={()=>onClient(c)}><span><b>{label(c.nombre||c.razon_social)}</b><small>{label(c.cliente_key)}</small></span><strong>{money(c.venta_mtd??c.ventaMtd)}</strong><span>{label(c.riesgo)}</span>→</button>)}{!clients.length&&!loading&&<div className="cc-empty">Sin clientes en esta cartera.</div>}</div><div className="cc-drill-orders"><h4>Pedidos B2B asociados</h4><span>{orders.length} pedidos</span></div></div>}{!loading&&!executives.length&&<div className="cc-empty">Sin ejecutivos para este territorio.</div>}</div>}
function Ranking({rows,loading,onRefresh}){return <section className="cc-ranking"><div className="cc-section-head"><div><span className="cc-subtitle">PULSO COMERCIAL</span><h2>Ranking por ejecutivo y canal</h2><p>Terreno, KAM y Televenta se comparan sin imponerles la misma métrica operativa.</p></div><button onClick={onRefresh} disabled={loading}>{loading?'Actualizando…':'Actualizar'}</button></div>{rows.length?<div className="cc-ranking-table"><div className="cc-ranking-head"><span>EJECUTIVO / CANAL</span><span>ROL</span><span>ZONA</span><span>VENTA MTD</span><span>META</span><span>AVANCE</span><span>CLIENTES</span><span>RIESGO</span></div>{rows.map((r,i)=><div className="cc-ranking-row" key={r.id||i}><span><b>{label(r.nombre)}</b></span><span>{label(r.rol)}</span><span>{label(r.zona)}</span><span>{money(r.venta)}</span><span>{money(r.meta)}</span><span>{pct(r.avance)}</span><span>{r.clientes.toLocaleString('es-CL')}</span><span>{r.riesgo}</span></div>)}</div>:<div className="cc-empty">Sin datos de ranking disponibles.</div>}</section>}
function Client360({cliente,clienteKey,onClose}){const [catalogAccess,setCatalogAccess]=useState({active:false,url:null});const [executives,setExecutives]=useState([]);const [selected,setSelected]=useState('');const [saving,setSaving]=useState(false);const [actionType,setActionType]=useState('volver');const [actionText,setActionText]=useState('');const [actionBusy,setActionBusy]=useState(false);const [actionOk,setActionOk]=useState(false);const [actions,setActions]=useState([]);const [opportunities,setOpportunities]=useState([]);const [oppBusy,setOppBusy]=useState(false);const loadActions=async()=>{if(clienteKey)setActions(await catalogPerformanceRepo.accionesCliente(clienteKey).catch(()=>[]))};useEffect(()=>{if(!clienteKey)return;Promise.allSettled([getCatalogAccess(clienteKey),ejecutivosRepo.listar(),catalogPerformanceRepo.accionesCliente(clienteKey),opportunityRepo.cliente(clienteKey)]).then(([a,e,n,o])=>{if(a.status==='fulfilled')setCatalogAccess(a.value||{});if(e.status==='fulfilled')setExecutives(e.value||[]);if(n.status==='fulfilled')setActions(n.value||[]);if(o.status==='fulfilled')setOpportunities(o.value||[])})},[clienteKey]);const assign=async()=>{if(!selected||!clienteKey)return;setSaving(true);try{const r=await clientesRepo.asignar(clienteKey,selected);if(r?.error)throw r.error;onClose();window.location.reload()}catch(_){setSaving(false)}};const createOpportunityAction=async(o)=>{setOppBusy(true);try{await catalogPerformanceRepo.crearAccion({clienteKey,ejecutivoId:selected||cliente.ejecutivo_id||null,nombreLocal:cliente.nombre||cliente.razon_social,tipo:'oportunidad',texto:`Oportunidad ${o.producto}: ${o.razon}. Potencial estimado ${money(o.oportunidadEstimada)}.`});await loadActions()}catch(_){ }finally{setOppBusy(false)}};const createAction=async()=>{if(!actionText.trim()||!clienteKey)return;setActionBusy(true);try{await catalogPerformanceRepo.crearAccion({clienteKey,ejecutivoId:selected||cliente.ejecutivo_id||null,nombreLocal:cliente.nombre||cliente.razon_social,tipo:actionType,texto:actionText});setActionText('');setActionOk(true);await loadActions();setTimeout(()=>setActionOk(false),1800)}catch(_){ }finally{setActionBusy(false)}};return <div className="cc-modal" role="dialog" aria-modal="true"><div className="cc-modal-card"><button className="cc-close" onClick={onClose}>×</button><span className="cc-subtitle">CLIENTE 360</span><h2>{label(cliente.nombre||cliente.razon_social||cliente.nombreCliente)}</h2><div className="cc-detail-grid"><div><span>VENTA MTD</span><b>{money(cliente.venta_mtd??cliente.ventaMtd)}</b></div><div><span>VARIACIÓN</span><b>{pct(cliente.variacion??cliente.variacion_mtd)}</b></div><div><span>RIESGO</span><b>{label(cliente.riesgo)}</b></div><div><span>SIN COMPRA</span><b>{Number(cliente.dias_sin_comprar??cliente.diasSinComprar??0)} días</b></div><div><span>EJECUTIVO</span><b>{label(cliente.ejecutivo||cliente.ejecutivo_nombre)}</b></div><div><span>ZONA</span><b>{label(cliente.zona)}</b></div></div><div className="cc-opportunity-panel"><div className="cc-section-head"><div><span className="cc-subtitle">OPORTUNIDAD EXPLICABLE</span><h3>Qué podría volver a comprar</h3><p>Basado en historial, frecuencia, stock y precio del cliente.</p></div></div>{opportunities.length?<div className="cc-opportunity-list">{opportunities.map((o,i)=><div className="cc-opportunity-card" key={`${o.sku}-${i}`}><div><b>{label(o.producto)}</b><span>{o.razon}</span></div><div><small>BRECHA</small><strong>{o.brechaEstimada.toLocaleString('es-CL')}</strong></div><div><small>STOCK</small><strong>{o.stockDisponible.toLocaleString('es-CL')}</strong></div><div><small>POTENCIAL</small><strong>{money(o.oportunidadEstimada)}</strong></div><button onClick={()=>createOpportunityAction(o)} disabled={oppBusy}>{oppBusy?'Guardando…':'Convertir en acción'}</button></div>)}</div>:<div className="cc-empty">No se detectaron oportunidades explicables con las señales actuales.</div>}</div><div className="cc-catalog-status"><span>CATÁLOGO B2B</span><strong>{catalogAccess.active?'● ACTIVO':'○ NO PUBLICADO'}</strong>{catalogAccess.url&&<button onClick={()=>window.open(catalogAccess.url,'_blank','noopener,noreferrer')}>Abrir catálogo</button>}</div><div className="cc-admin-action"><h3>Acción gerencial</h3><label>Asignar ejecutivo</label><select value={selected} onChange={e=>setSelected(e.target.value)} disabled={saving}><option value="">Mantener actual</option>{executives.map(e=><option key={e.id} value={e.id}>{e.nombre} · {label(e.zona)}</option>)}</select><button onClick={assign} disabled={saving||!selected}>{saving?'Guardando…':'Confirmar asignación'}</button><div className="cc-action-form"><label>Registrar acción</label><select value={actionType} onChange={e=>setActionType(e.target.value)} disabled={actionBusy}>{ACTION_TYPES.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><textarea rows={3} value={actionText} onChange={e=>setActionText(e.target.value)} placeholder="Qué debe hacerse con este cliente…" disabled={actionBusy}/><button onClick={createAction} disabled={actionBusy||!actionText.trim()}>{actionBusy?'Guardando…':actionOk?'✓ Acción registrada':'Registrar acción'}</button></div>{actions.length>0&&<div className="cc-action-history"><h4>Últimas acciones</h4>{actions.slice(0,5).map((a,i)=><div key={a.id||i}><b>{label(a.tipo)}</b><span>{label(a.texto)}</span></div>)}</div>}</div></div></div>}
function B2BPerformance({data,loading,onRefresh}){return <section className="cc-b2b-performance"><div className="cc-section-head"><div><span className="cc-subtitle">CANAL B2B</span><h2>Performance del catálogo</h2></div><button onClick={onRefresh} disabled={loading}>{loading?'Actualizando…':'Actualizar'}</button></div><div className="cc-kpis"><div><span>CATÁLOGOS ACTIVOS</span><b>{data?data.activeCatalogs.toLocaleString('es-CL'):'—'}</b></div><div><span>PEDIDOS</span><b>{data?data.orders.toLocaleString('es-CL'):'—'}</b></div><div><span>CLIENTES COMPRADORES</span><b>{data?data.orderingClients.toLocaleString('es-CL'):'—'}</b></div><div><span>VENTA</span><b>{data?money(data.sales):'—'}</b></div><div><span>TICKET PROMEDIO</span><b>{data?money(data.avgTicket):'—'}</b></div><div><span>RECOMPRA</span><b>{data?pct(data.repurchaseRate):'—'}</b></div><div><span>RECUPERADOS</span><b>{data?data.recoveredClients.toLocaleString('es-CL'):'—'}</b></div></div></section>}
function RiskQueue({rows,loading,onRefresh,onOpen}){return <section className="cc-risk-queue"><div className="cc-section-head"><div><span className="cc-subtitle">ACCIÓN GERENCIAL</span><h2>Clientes en riesgo</h2><p>Prioridad comercial basada en riesgo, días sin compra y caída de venta.</p></div><button onClick={onRefresh} disabled={loading}>{loading?'Actualizando…':'Actualizar'}</button></div>{rows.length?<div className="cc-risk-table"><div className="cc-risk-head"><span>CLIENTE</span><span>EJECUTIVO</span><span>RIESGO</span><span>SIN COMPRA</span><span>VENTA MTD</span><span>VARIACIÓN</span><span>ACCIÓN</span></div>{rows.map((c,i)=><div className="cc-risk-row" key={c.id||c.cliente_key||i}><span><b>{label(c.nombre||c.razon_social)}</b><small>{label(c.cliente_key||c.rut)}</small></span><span>{label(c.ejecutivo||c.ejecutivo_nombre)}</span><span>{label(c.riesgo)}</span><span>{Number(c.dias_sin_comprar??c.diasSinComprar??0).toLocaleString('es-CL')} días</span><span>{money(c.venta_mtd??c.ventaMtd)}</span><span>{pct(c.variacion??c.variacion_mtd)}</span><button onClick={()=>onOpen(c)}>Ver 360°</button></div>)}</div>:<div className="cc-empty">No hay clientes que cumplan los criterios actuales de riesgo.</div>}</section>}
export default function ControlCenter(){const [performance,setPerformance]=useState(null);const [risks,setRisks]=useState([]);const [ranking,setRanking]=useState([]);const [territory,setTerritory]=useState([]);const [attribution,setAttribution]=useState([]);const [opportunities,setOpportunities]=useState([]);const [priority,setPriority]=useState([]);const [selectedClient,setSelectedClient]=useState(null);const [drillSelection,setDrillSelection]=useState(null);const [loading,setLoading]=useState(true);const load=async()=>{setLoading(true);try{const [p,r,k,t,a,o,pr]=await Promise.all([catalogPerformanceRepo.resumen(),catalogPerformanceRepo.riskQueue(),catalogPerformanceRepo.ranking(),catalogPerformanceRepo.canalTerritorial(),catalogPerformanceRepo.catalogAttribution(),opportunityRepo.resumen(),commercialPriorityRepo.resumen()]);setPerformance(p);setRisks(r);setRanking(k);setTerritory(t);setAttribution(a);setOpportunities(o);setPriority(pr)}finally{setLoading(false)}};useEffect(()=>{load()},[]);const openClient=c=>setSelectedClient(c);const openOpportunity=o=>{if(!o?.clienteKey)return;setSelectedClient({cliente_key:o.clienteKey,nombre:o.nombreCliente||o.clienteKey,ejecutivo_id:o.ejecutivoId||null,ejecutivo:o.ejecutivo||null,zona:o.zona||null,venta_mtd:0,variacion:null,riesgo:'Oportunidad',dias_sin_comprar:o.diasSinCompra})};return <main className="control-center"><B2BPerformance data={performance} loading={loading} onRefresh={load}/><CommercialPriority rows={priority} loading={loading} onRefresh={load} onOpen={openClient}/><OpportunitySummary rows={opportunities} loading={loading} onRefresh={load} onOpen={openOpportunity}/><B2BAttribution rows={attribution} loading={loading} onRefresh={load} onOpenDrill={(canal,zona)=>setDrillSelection({canal,zona})}/><ChannelTerritory rows={territory} loading={loading} onRefresh={load}/><Ranking rows={ranking} loading={loading} onRefresh={load}/><RiskQueue rows={risks} loading={loading} onRefresh={load} onOpen={openClient}/>{drillSelection&&<DrillDown selection={drillSelection} onClose={()=>setDrillSelection(null)} onClient={openClient}/>} {selectedClient&&<Client360 cliente={selectedClient} clienteKey={selectedClient.cliente_key||selectedClient.id} onClose={()=>setSelectedClient(null)}/>}</main>}
