import { supabase } from '../../lib/supabase.js'
import { listarPedidosHistorial, getPedidoById } from '../../lib/pedido.js'
function result(data,error){if(error)throw error;return data||[]}
const isCatalogOrder=p=>p&&p.cliente_key&&String(p.fuente||'').toLowerCase()==='catalogo_publico'
const isClosedOrder=p=>!['borrador','cancelado'].includes(String(p?.estado||'').toLowerCase())
export const ventasRepo={async resumen(){const{data,error}=await supabase.from('gerencia').select('*');return result(data,error)},async tendencia(){const{data,error}=await supabase.from('tendencia').select('*');return result(data,error)}}
export const clientesRepo={async resumen(limit=3000){const{data,error}=await supabase.from('gerencia_clientes').select('*').order('venta_mtd',{ascending:false}).limit(limit);return result(data,error)},async cartera(ejecutivoId,limit=800){let q=supabase.from('cartera').select('*').limit(limit);if(ejecutivoId)q=q.eq('ejecutivo_id',ejecutivoId);const{data,error}=await q;return result(data,error)},async mix(clienteKey,limit=800){if(!clienteKey)return[];const{data,error}=await supabase.from('ventas_lineas').select('sku_canon,producto_nombre,cantidad,venta_neta_clp,fecha').eq('cliente_key',String(clienteKey)).order('fecha',{ascending:false}).limit(limit);return result(data,error)},async historial(clienteKey,limit=120){if(!clienteKey)return[];const{data,error}=await supabase.from('ventas_lineas').select('sku_canon,producto_nombre,cantidad,venta_neta_clp,fecha').eq('cliente_key',String(clienteKey)).order('fecha',{ascending:false}).limit(limit);return result(data,error)},async asignar(clienteKey,ejecutivoId){return supabase.from('clientes').update({ejecutivo_id:ejecutivoId}).eq('cliente_key',String(clienteKey))}}
export const ejecutivosRepo={async listar(){const{data,error}=await supabase.from('ejecutivos').select('id,nombre,zona,rol');return result(data,error)}}
export const stockRepo={async listar(limit=500){const{data,error}=await supabase.from('stock').select('*').limit(limit);return result(data,error)}}
export const catalogoRepo={async cliente(clienteKey,limit=500){if(!clienteKey)return[];const{data,error}=await supabase.from('oferta_cliente_items').select('*').eq('cliente_key',String(clienteKey)).limit(limit);return result(data,error)}}
export const pedidosRepo={async cliente(clienteKey,limit=100){if(!clienteKey)return[];const r=await listarPedidosHistorial({clienteKey:String(clienteKey),dias:0,limit});if(r.error)throw r.error;return r.data||[]},async detalle(id){const r=await getPedidoById(id);if(r.error)throw r.error;return r.data||null}}
export const catalogPerformanceRepo={
async resumen(){const[{data:ofertas,error:oe},{data:pedidos,error:pe}]=await Promise.all([supabase.from('ofertas_cliente').select('id,cliente_key,activo,actualizado_en'),supabase.from('pedidos').select('id,cliente_key,estado,fuente,total_estimado,creado_en,lineas').order('creado_en',{ascending:false}).limit(5000)]);if(oe)throw oe;if(pe)throw pe;const activeKeys=new Set((ofertas||[]).filter(o=>o.activo).map(o=>String(o.cliente_key)));const catalogOrders=(pedidos||[]).filter(p=>activeKeys.has(String(p.cliente_key))&&isCatalogOrder(p));const completed=catalogOrders.filter(isClosedOrder);const completedSales=completed.reduce((a,p)=>a+Number(p.total_estimado||0),0);const clients=new Map();for(const p of completed){const key=String(p.cliente_key);const x=clients.get(key)||{orders:0,sales:0,first:null,last:null};x.orders++;x.sales+=Number(p.total_estimado||0);const date=p.creado_en?new Date(p.creado_en):null;if(date&&!Number.isNaN(date.getTime())){if(!x.first||date<x.first)x.first=date;if(!x.last||date>x.last)x.last=date}clients.set(key,x)}const repeatClients=[...clients.values()].filter(x=>x.orders>=2).length;const recoveredClients=[...clients.values()].filter(x=>x.orders>=1&&x.first&&x.last&&x.first.getTime()!==x.last.getTime()).length;return{activeCatalogs:activeKeys.size,orders:catalogOrders.length,orderingClients:clients.size,sales:completedSales,avgTicket:completed.length?completedSales/completed.length:0,pendingOrders:catalogOrders.filter(p=>['borrador','recibido'].includes(String(p.estado||'').toLowerCase())).length,completedOrders:completed.length,repeatClients,repurchaseRate:clients.size?repeatClients/clients.size:0,recoveredClients,source:'catalogo_publico'}},
async riskQueue(limit=100){const{data,error}=await supabase.from('gerencia_clientes').select('*').order('dias_sin_comprar',{ascending:false}).limit(Math.max(limit*4,400));if(error)throw error;return(data||[]).filter(c=>{const risk=String(c.riesgo||'').toLowerCase();const days=Number(c.dias_sin_comprar??c.diasSinComprar??0);const variation=Number(c.variacion??c.variacion_mtd??0);return risk==='alto'||risk==='crítico'||risk==='critico'||days>=30||variation<=-0.2}).sort((a,b)=>{const rank=x=>['crítico','critico','alto','medio','bajo'].indexOf(String(x.riesgo||'').toLowerCase());const rr=rank(a)-rank(b);if(rr)return rr;return Number(b.dias_sin_comprar??b.diasSinComprar??0)-Number(a.dias_sin_comprar??a.diasSinComprar??0)}).slice(0,limit)},
async crearAccion({clienteKey,ejecutivoId,nombreLocal,tipo='otro',texto}){if(!clienteKey||!texto?.trim())throw new Error('clienteKey y texto son obligatorios');const{data,error}=await supabase.from('notas_cliente').insert({ejecutivo_id:ejecutivoId||null,cliente_key:String(clienteKey),nombre_local:nombreLocal||null,tipo,texto:texto.trim()}).select().single();if(error)throw error;return data},
async accionesCliente(clienteKey,limit=30){if(!clienteKey)return[];const{data,error}=await supabase.from('notas_cliente').select('*').eq('cliente_key',String(clienteKey)).order('created_at',{ascending:false}).limit(limit);return result(data,error)},
async ranking(){const[{data:clientes,error:ce},{data:ejecutivos,error:ee}]=await Promise.all([supabase.from('gerencia_clientes').select('*').limit(5000),supabase.from('ejecutivos').select('id,nombre,zona,rol')]);if(ce)throw ce;if(ee)throw ee;const people=new Map((ejecutivos||[]).map(e=>[String(e.id),e]));const groups=new Map();for(const c of clientes||[]){const id=c.ejecutivo_id?String(c.ejecutivo_id):null;const e=id?people.get(id):null;const canal=String(c.canal||e?.rol||'Terreno').toUpperCase();const key=id||`canal:${canal}`;const x=groups.get(key)||{id,nombre:e?.nombre||canal,rol:e?.rol||canal,zona:e?.zona||c.zona||'—',venta:0,meta:0,clientes:0,riesgo:0};x.venta+=Number(c.venta_mtd??c.ventaMtd??0);x.meta+=Number(c.meta_mtd??c.metaMtd??0);x.clientes++;if(['alto','crítico','critico'].includes(String(c.riesgo||'').toLowerCase()))x.riesgo++;groups.set(key,x)}return[...groups.values()].map(x=>({...x,avance:x.meta?x.venta/x.meta:null})).sort((a,b)=>b.venta-a.venta)},
async canalTerritorial(){const{data,error}=await supabase.from('gerencia_clientes').select('ejecutivo_id,canal,zona,venta_mtd,meta_mtd,riesgo').limit(5000);if(error)throw error;const groups=new Map();for(const c of data||[]){const canal=String(c.canal||'TERRENO').toUpperCase();const zona=String(c.zona||'SIN ZONA');const key=`${canal}|||${zona}`;const x=groups.get(key)||{canal,zona,venta:0,meta:0,clientes:0,riesgo:0};x.venta+=Number(c.venta_mtd||0);x.meta+=Number(c.meta_mtd||0);x.clientes++;if(['alto','crítico','critico'].includes(String(c.riesgo||'').toLowerCase()))x.riesgo++;groups.set(key,x)}return[...groups.values()].map(x=>({...x,avance:x.meta?x.venta/x.meta:null})).sort((a,b)=>b.venta-a.venta)},
async catalogAttribution(){const[{data:pedidos,error:pe},{data:clientes,error:ce},{data:ejecutivos,error:ee}]=await Promise.all([supabase.from('pedidos').select('id,cliente_key,estado,fuente,total_estimado,creado_en').eq('fuente','catalogo_publico').order('creado_en',{ascending:false}).limit(5000),supabase.from('gerencia_clientes').select('cliente_key,ejecutivo_id,canal,zona').limit(5000),supabase.from('ejecutivos').select('id,nombre,rol,zona')]);if(pe)throw pe;if(ce)throw ce;if(ee)throw ee;const byClient=new Map((clientes||[]).map(c=>[String(c.cliente_key),c]));const byExec=new Map((ejecutivos||[]).map(e=>[String(e.id),e]));const groups=new Map();for(const p of pedidos||[]){if(!isClosedOrder(p))continue;const c=byClient.get(String(p.cliente_key));const e=c?.ejecutivo_id?byExec.get(String(c.ejecutivo_id)):null;const canal=String(c?.canal||e?.rol||'SIN CANAL').toUpperCase();const zona=String(c?.zona||e?.zona||'SIN ZONA');const key=`${canal}|||${zona}`;const x=groups.get(key)||{canal,zona,venta:0,pedidos:0,clientes:new Set()};x.venta+=Number(p.total_estimado||0);x.pedidos++;x.clientes.add(String(p.cliente_key));groups.set(key,x)}return[...groups.values()].map(x=>({canal:x.canal,zona:x.zona,venta:x.venta,pedidos:x.pedidos,clientes:x.clientes.size})).sort((a,b)=>b.venta-a.venta)},
}
export const notasRepo={async listar(limit=300){const{data,error}=await supabase.from('notas_cliente').select('*').limit(limit);return result(data,error)}}
